//! S9E-02 `any_changed_field_breaks_the_signature` [M]: for each field of `CredentialClaims` a copy with
//! that one field changed is refused, and the signature covers every field; likewise each field of the
//! `Certificate`. The tables are generated by a macro that lists the fields ONCE and destructures the
//! struct without `..`, so a new field without a test fails to compile.

use azlin_creds::{
    verify_credential, Certificate, CredError, Credential, CredentialClaims, Scope, Scopes,
    SsoClaim,
};
use azlin_regbase::{
    AccountId, CredentialNonce, DeviceId, FamilyId, KeyEpoch, MemberId, MetaGroupId, PolicyEpoch,
    PublicKey32, Signature64, SmallText,
};

use crate::support::*;

macro_rules! claims_table {
    ($table:ident, $exhaustive:ident { $( $field:ident => |$c:ident| $body:expr ),+ $(,)? }) => {
        fn $table() -> Vec<(&'static str, fn(&mut CredentialClaims))> {
            vec![ $( (stringify!($field), (|$c: &mut CredentialClaims| { $body; }) as fn(&mut CredentialClaims)) ),+ ]
        }
        /// Adding a field to `CredentialClaims` without adding it to the table does not compile.
        #[allow(dead_code)]
        fn $exhaustive(v: CredentialClaims) {
            let CredentialClaims { $( $field: _ ),+ } = v;
        }
    };
}

claims_table!(credential_mutations, credential_fields_are_all_listed {
    account => |c| c.account = AccountId::from_bytes([0xEE; 16]),
    member => |c| c.member = MemberId::from_bytes([0xEE; 16]),
    device => |c| c.device = if c.device.is_some() { None } else { Some(DeviceId::from_bytes([0xEE; 16])) },
    family => |c| c.family = if c.family.is_some() { None } else { Some(FamilyId::from_bytes([0xEE; 16])) },
    policy_epoch => |c| c.policy_epoch = PolicyEpoch::new(c.policy_epoch.get() + 1),
    scopes => |c| c.scopes = if c.scopes.is_some() {
        None
    } else {
        Some(Scopes::new(vec![Scope::LogAppend { log: azlin_creds::LogRef::from_bytes([0xEE; 16]) }]).expect("one scope"))
    },
    issued_at => |c| c.issued_at = at(c.issued_at.as_secs() + 1),
    expires_at => |c| c.expires_at = at(c.expires_at.as_secs() + 1),
    key_epoch => |c| c.key_epoch = KeyEpoch::new(c.key_epoch.get() + 1),
    nonce => |c| c.nonce = CredentialNonce::from_bytes([0xEE; 16]),
    sso => |c| c.sso = if c.sso.is_some() {
        None
    } else {
        Some(SsoClaim { provider: SmallText::new("other").expect("a provider"), auth_time: at(ISSUED - 1) })
    },
});

fn scopes_of_one() -> Scopes {
    Scopes::new(vec![Scope::LogAppend {
        log: azlin_creds::LogRef::from_bytes([0x66; 16]),
    }])
    .expect("one scope")
}

/// Four bases, so that every field has a base on which changing it keeps the claims well shaped (the
/// shape rules refuse a device credential without a family and a credential of no device without
/// scopes before the signature is looked at).
fn bases() -> Vec<(&'static str, CredentialClaims)> {
    let device_credential = {
        let mut c = claims_of(grant());
        c.sso = Some(SsoClaim {
            provider: SmallText::new("entra-contoso").expect("a provider"),
            auth_time: at(ISSUED - 10),
        });
        c
    };
    let narrowed_device = {
        let mut c = claims_of(grant());
        c.scopes = Some(scopes_of_one());
        c
    };
    let app_principal = {
        let mut c = claims_of(grant());
        c.device = None;
        c.family = None;
        c.scopes = Some(scopes_of_one());
        c.sso = Some(SsoClaim {
            provider: SmallText::new("entra-contoso").expect("a provider"),
            auth_time: at(ISSUED - 10),
        });
        c
    };
    let link_like = {
        let mut c = claims_of(grant());
        c.device = None;
        c.scopes = Some(scopes_of_one());
        c
    };
    vec![
        ("device credential", device_credential),
        ("narrowed device credential", narrowed_device),
        ("app principal", app_principal),
        ("link-like", link_like),
    ]
}

#[test]
fn s9e_02_any_changed_claim_breaks_the_signature() {
    let f = fixture();
    let mutations = credential_mutations();
    assert_eq!(mutations.len(), 11, "the eleven claims of 5.11 and D-1c");
    let mut covered: Vec<(&str, &str)> = Vec::new();
    for (base_name, base) in bases() {
        let original = signed_credential(&f.cred, f.cert, base.clone());
        verify_credential(&original, &f.anchors, &placement(), now(ISSUED), &f.rules)
            .unwrap_or_else(|e| panic!("the control ({base_name}) must verify: {e}"));
        for (field, mutate) in &mutations {
            let mut changed = base.clone();
            mutate(&mut changed);
            assert_ne!(
                changed, base,
                "{field} on {base_name}: the mutation changes nothing"
            );
            let forged = Credential::from_parts(changed, f.cert, *original.signature())
                .expect("the changed claims encode");
            let verdict =
                verify_credential(&forged, &f.anchors, &placement(), now(ISSUED), &f.rules);
            let error = verdict.expect_err(&format!("{field} changed on {base_name} must fail"));
            match (*field, error) {
                // The epoch of a credential is bound to its certificate's before any signature is read.
                ("key_epoch", CredError::CertMismatch) => covered.push((*field, "CertMismatch")),
                (_, CredError::BadSignature) => covered.push((*field, "BadSignature")),
                // A change that breaks the shape is refused by the shape rule first.
                (_, CredError::Malformed) => {}
                (field, other) => panic!("{field} on {base_name}: unexpected refusal {other:?}"),
            }
        }
    }
    for (field, _) in &mutations {
        let wanted = if *field == "key_epoch" {
            "CertMismatch"
        } else {
            "BadSignature"
        };
        assert!(
            covered.contains(&(*field, wanted)),
            "no base proves that the signature covers {field}"
        );
    }
}

macro_rules! cert_table {
    ($table:ident, $exhaustive:ident { $( $field:ident => $expect:expr, |$c:ident| $body:expr ),+ $(,)? }) => {
        fn $table() -> Vec<(&'static str, CredError, fn(&mut Certificate))> {
            vec![ $( (stringify!($field), $expect, (|$c: &mut Certificate| { $body; }) as fn(&mut Certificate)) ),+ ]
        }
        /// Adding a field to `Certificate` without adding it to the table does not compile.
        #[allow(dead_code)]
        fn $exhaustive(v: Certificate) {
            let Certificate { $( $field: _ ),+ } = v;
        }
    };
}

cert_table!(certificate_mutations, certificate_fields_are_all_listed {
    group => CredError::UnknownIdentity, |c| c.group = MetaGroupId::new(c.group.get() + 1),
    epoch => CredError::CertMismatch, |c| c.epoch = KeyEpoch::new(c.epoch.get() + 1),
    cred_pub => CredError::BadCert, |c| c.cred_pub = PublicKey32::from_bytes([0xEE; 32]),
    identity_pub => CredError::UnknownIdentity, |c| c.identity_pub = PublicKey32::from_bytes([0xEE; 32]),
    not_before => CredError::BadCert, |c| c.not_before = at(c.not_before.as_secs() + 1),
    not_after => CredError::BadCert, |c| c.not_after = at(c.not_after.as_secs() + 1),
    identity_sig => CredError::BadCert, |c| {
        let mut bytes = *c.identity_sig.as_bytes();
        bytes[3] ^= 0x01;
        c.identity_sig = Signature64::from_bytes(bytes);
    },
});

#[test]
fn s9e_02_any_changed_certificate_field_is_refused() {
    let f = fixture();
    let (_, credential) = issue_fixture();
    let mutations = certificate_mutations();
    assert_eq!(
        mutations.len(),
        7,
        "the six fields of the body and the signature"
    );
    for (field, expected, mutate) in mutations {
        let mut cert = f.cert;
        mutate(&mut cert);
        assert_ne!(cert, f.cert, "{field}: the mutation changes nothing");
        let forged =
            Credential::from_parts(credential.claims().clone(), cert, *credential.signature())
                .expect("encodes");
        assert_eq!(
            verify_credential(&forged, &f.anchors, &placement(), now(ISSUED), &f.rules).err(),
            Some(expected),
            "{field} changed"
        );
    }
}
